document.addEventListener("astro:page-load",()=>{const e=document.getElementById("back-to-top");if(!e)return;const t=()=>{window.scrollY>500?e.classList.add("is-visible"):(e.classList.remove("is-visible"),e.blur())};window.addEventListener("scroll",t,{passive:!0}),e.addEventListener("click",()=>{window.scrollTo({top:0,behavior:window.matchMedia("(prefers-reduced-motion: reduce)").matches?"auto":"smooth"})}),t()});
